          ]
        },
        "poor": {
          "criteria": [
            "로그에서 확인한 내용 없이 오류 원인만 제시한다.",
            "로그의 패턴을 설명하지 못하거나 관찰 내용이 판단한 원인을 뒷받침하지 못한다."
          ]
        }
      }
